@Service
public class PuntoRetiroService {
 private final JdbcTemplate jdbc;private final PasswordEncoder encoder;private final CredencialService credenciales;private final EntregaService entregas;private final PedidoService pedidos;private final PagoService pagos;private final CodigoRetiroService codigos;private final JsonMapper json=JsonMapper.builder().build();
 public PuntoRetiroService(JdbcTemplate jdbc,PasswordEncoder encoder,CredencialService credenciales,EntregaService entregas,PedidoService pedidos,PagoService pagos,CodigoRetiroService codigos){this.jdbc=jdbc;this.encoder=encoder;this.credenciales=credenciales;this.entregas=entregas;this.pedidos=pedidos;this.pagos=pagos;this.codigos=codigos;}
 public record Cuenta(String usuario,String correo,String responsable,boolean activa,boolean cobros,long version,Instant creadaEn){}
 public record Punto(UUID punto,String codigo,String nombre,Cuenta cuenta){}
 public record Contexto(UUID punto,String nombre,String responsable,boolean cobros,long porLlegar,long disponibles,long entregados){}
 public record Fila(UUID pedido,long numero,long version,String cliente,String correo,String estado,String recorrido,String saldo,String medio,Instant movimiento,String franja){}
 public record Bandeja(List<Fila> pedidos,long total,int pagina){}
 public record Trabajo(String nombre,int paginas,int copias){}
 public record Ficha(Fila pedido,List<Trabajo> trabajos,EntregaService.Vista entrega,List<String> medios){}
 public record Movimiento(long pedido,String tipo,String importe,String medio,String referencia,String responsable,Instant fecha,boolean enPunto){}
 public record Finanzas(String pendiente,String efectivo,String transferencia,long total,List<Movimiento> movimientos,int pagina,String desde,String hasta){}
 private record Acceso(long punto,long usuario,UUID publico,String nombre,String responsable,boolean cobros){}
 private void locks(){for(long l:new long[]{764003,764001,764002,764004})jdbc.execute("SELECT pg_advisory_xact_lock("+l+")");}
 private long admin(String correo){var ids=jdbc.query("SELECT u.id_usuario FROM lamontana.usuario u JOIN lamontana.rol r USING(id_rol) WHERE u.correo=? AND u.estado='ACTIVO' AND r.codigo='ADMIN_ADMIN' AND r.activo",(r,n)->r.getLong(1),correo);if(ids.isEmpty())throw error(HttpStatus.FORBIDDEN,"Sólo administración puede gestionar estas cuentas.");return ids.get(0);}
 private static final String NOMBRE="coalesce((SELECT d.nombre FROM lamontana.configuracion_definicion_punto d JOIN lamontana.configuracion_version v USING(id_configuracion_version) WHERE d.id_punto_entrega=pt.id_punto_entrega AND v.estado IN ('ACTIVA','HISTORICA') ORDER BY (v.estado='ACTIVA') DESC,v.numero_version DESC LIMIT 1),pt.codigo)";
 @Transactional(readOnly=true) public List<Punto> cuentas(String correo){admin(correo);return jdbc.query("SELECT pt.codigo_publico,pt.codigo,"+NOMBRE+" AS nombre,u.alias_acceso,u.correo,cp.* FROM lamontana.punto_entrega pt LEFT JOIN lamontana.cuenta_punto cp USING(id_punto_entrega) LEFT JOIN lamontana.usuario u USING(id_usuario) ORDER BY pt.codigo",(r,n)->new Punto(r.getObject("codigo_publico",UUID.class),r.getString("codigo"),r.getString("nombre"),r.getString("alias_acceso")==null?null:new Cuenta(r.getString("alias_acceso"),r.getString("correo"),r.getString("responsable"),r.getBoolean("activa"),r.getBoolean("cobros"),r.getLong("version"),r.getTimestamp("creada_en").toInstant())));}
 private Punto punto(UUID id,String correo){return cuentas(correo).stream().filter(p->p.punto().equals(id)).findFirst().orElseThrow(()->error(HttpStatus.NOT_FOUND,"Punto inexistente."));}
 @Transactional public Punto crear(UUID id,Alta in,String correo){locks();long actor=admin(correo);String hash=hash(List.of(id,in.usuario(),in.correo().strip().toLowerCase(Locale.ROOT),in.responsable().strip(),in.cobros()));
  if(replay(in.operacion(),id,actor,hash)){var pass=jdbc.queryForObject("SELECT u.hash_contrasena FROM lamontana.cuenta_punto cp JOIN lamontana.punto_entrega pt USING(id_punto_entrega) JOIN lamontana.usuario u USING(id_usuario) WHERE pt.codigo_publico=?",String.class,id);if(!encoder.matches(in.contrasena(),pass))throw error(HttpStatus.CONFLICT,"La cuenta ya fue creada con otras credenciales.");return punto(id,correo);}
  var p=punto(id,correo);if(p.cuenta()!=null)throw error(HttpStatus.CONFLICT,"Este punto ya tiene su única cuenta.");
  if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM lamontana.usuario WHERE correo=? OR alias_acceso=?)",Boolean.class,in.correo().strip().toLowerCase(Locale.ROOT),in.usuario())))throw error(HttpStatus.CONFLICT,"El usuario o correo ya está utilizado.");
  long user=jdbc.queryForObject("INSERT INTO lamontana.usuario(codigo_publico,id_rol,correo,alias_acceso,hash_contrasena,nombre,apellido,estado,debe_cambiar_contrasena) SELECT ?,id_rol,?,?,?,?,?,'ACTIVO',true FROM lamontana.rol WHERE codigo='EMPLEADO' RETURNING id_usuario",Long.class,UUID.randomUUID(),in.correo().strip().toLowerCase(Locale.ROOT),in.usuario(),encoder.encode(in.contrasena()),p.nombre().substring(0,Math.min(100,p.nombre().length())),in.responsable().strip());
  jdbc.update("INSERT INTO lamontana.cuenta_punto(id_punto_entrega,id_usuario,responsable,cobros) SELECT id_punto_entrega,?,?,? FROM lamontana.punto_entrega WHERE codigo_publico=?",user,in.responsable().strip(),in.cobros(),id);evento(in.operacion(),id,actor,"CREAR",hash);return punto(id,correo);
 }
 @Transactional public Punto cambiar(UUID id,Cambio in,String correo){locks();long actor=admin(correo);String hash=hash(List.of(id,in));if(replay(in.operacion(),id,actor,hash))return punto(id,correo);var p=punto(id,correo);if(p.cuenta()==null||p.cuenta().version()!=in.version())throw error(HttpStatus.CONFLICT,"La cuenta cambió. Actualizá antes de continuar.");
  long user=jdbc.queryForObject("SELECT cp.id_usuario FROM lamontana.cuenta_punto cp JOIN lamontana.punto_entrega pt USING(id_punto_entrega) WHERE pt.codigo_publico=?",Long.class,id);
  jdbc.update("UPDATE lamontana.cuenta_punto SET responsable=?,activa=?,cobros=?,version=version+1 WHERE id_usuario=?",in.responsable().strip(),in.activa(),in.cobros(),user);jdbc.update("UPDATE lamontana.usuario SET apellido=?,estado=?,version=version+1,fecha_desactivacion=CASE WHEN ? THEN NULL ELSE clock_timestamp() END WHERE id_usuario=?",in.responsable().strip(),in.activa()?"ACTIVO":"DESACTIVADO",in.activa(),user);credenciales.revocar(user);evento(in.operacion(),id,actor,"ACTUALIZAR",hash);return punto(id,correo);
 }
 private boolean replay(UUID op,UUID point,long actor,String hash){var rows=jdbc.query("SELECT pt.codigo_publico,e.id_actor,e.huella FROM lamontana.evento_cuenta_punto e JOIN lamontana.punto_entrega pt USING(id_punto_entrega) WHERE e.id_operacion=?",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getLong(2),r.getString(3)},op);if(rows.isEmpty())return false;var row=rows.get(0);if(!row[0].equals(point)||(long)row[1]!=actor||!row[2].equals(hash))throw error(HttpStatus.CONFLICT,"La operación ya se utilizó con otros datos.");return true;}
 private void evento(UUID op,UUID point,long actor,String action,String hash){jdbc.update("INSERT INTO lamontana.evento_cuenta_punto(id_operacion,id_punto_entrega,id_actor,accion,huella) SELECT ?,id_punto_entrega,?,?,? FROM lamontana.punto_entrega WHERE codigo_publico=?",op,actor,action,hash,point);}
 private Acceso acceso(String correo){var rows=jdbc.query("SELECT cp.*,pt.codigo_publico,"+NOMBRE+" AS nombre FROM lamontana.cuenta_punto cp JOIN lamontana.usuario u USING(id_usuario) JOIN lamontana.punto_entrega pt USING(id_punto_entrega) WHERE u.correo=? AND u.estado='ACTIVO' AND cp.activa",(r,n)->new Acceso(r.getLong("id_punto_entrega"),r.getLong("id_usuario"),r.getObject("codigo_publico",UUID.class),r.getString("nombre"),r.getString("responsable"),r.getBoolean("cobros")),correo);if(rows.isEmpty())throw error(HttpStatus.FORBIDDEN,"No hay un punto activo asignado a esta cuenta.");return rows.get(0);}
 private static final String FROM=" FROM lamontana.pedido_actual p JOIN lamontana.usuario u ON u.id_usuario=p.id_usuario_creador JOIN lamontana.cotizacion c USING(id_cotizacion) JOIN lamontana.reserva_entrega r USING(id_pedido) JOIN lamontana.punto_entrega pt ON pt.codigo_publico=r.destino_publico WHERE pt.id_punto_entrega=? AND r.modalidad='RETIRO_PUNTO_ENTREGA' AND r.estado IN ('ACTIVA','CUMPLIDA') ";
 private static final String TRANSIT="p.estado='LISTO_PARA_ENTREGA' AND lamontana.estado_logistico(p.id_pedido)='EN_VIAJE'",READY="p.estado='LISTO_PARA_ENTREGA' AND lamontana.estado_logistico(p.id_pedido)='DISPONIBLE_PUNTO'",DONE="p.estado IN ('ENTREGADO','CERRADO')";
 private static final String SELECT="SELECT p.codigo_publico,p.id_pedido,p.version,u.nombre||' '||u.apellido AS cliente,u.correo,p.estado,lamontana.estado_logistico(p.id_pedido) AS recorrido,greatest(p.total-coalesce((SELECT sum(n.neto) FROM lamontana.aplicacion_pago_neta n WHERE n.id_cotizacion=p.id_cotizacion),0),0) AS saldo,c.oferta->>'medioPago' AS medio,coalesce((SELECT max(h.fecha) FROM lamontana.historial_estado_pedido h WHERE h.id_pedido=p.id_pedido),p.confirmada_en) AS movimiento,r.fecha_local||' · '||r.apertura||'–'||r.cierre AS franja";
 private Fila fila(java.sql.ResultSet r,int n)throws java.sql.SQLException{return new Fila(r.getObject("codigo_publico",UUID.class),r.getLong("id_pedido"),r.getLong("version"),r.getString("cliente"),r.getString("correo"),r.getString("estado"),r.getString("recorrido"),r.getBigDecimal("saldo").toPlainString(),r.getString("medio"),r.getTimestamp("movimiento").toInstant(),r.getString("franja"));}
 @Transactional(readOnly=true) public Contexto contexto(String correo){var a=acceso(correo);return new Contexto(a.publico(),a.nombre(),a.responsable(),a.cobros(),contar(a,TRANSIT),contar(a,READY),contar(a,DONE));}
 private long contar(Acceso a,String condition){return jdbc.queryForObject("SELECT count(*)"+FROM+" AND ("+condition+")",Long.class,a.punto());}
 @Transactional public Bandeja buscar(Buscar in,String correo){locks();var a=acceso(correo);String state=switch(in.estado()){case "POR_LLEGAR"->TRANSIT;case "DISPONIBLES"->READY;case "ENTREGADOS"->DONE;default->throw error(HttpStatus.BAD_REQUEST,"Estado inválido.");};if(in.pagina()>100000)throw error(HttpStatus.BAD_REQUEST,"Página inválida.");String text=in.texto()==null?"":in.texto().strip();var args=new ArrayList<Object>();args.add(a.punto());String filter=" AND ("+state+")";
  if(text.toUpperCase(Locale.ROOT).matches("[A-HJ-NP-Z2-9]{8}")){
   var found=jdbc.query("SELECT p.codigo_publico"+FROM+" AND ("+TRANSIT+" OR "+READY+") AND EXISTS(SELECT 1 FROM lamontana.codigo_entrega ce WHERE ce.id_pedido=p.id_pedido AND ce.revocado_en IS NULL AND ce.utilizado_en IS NULL)", (r,n)->r.getObject(1,UUID.class),a.punto());
   UUID match=null;for(UUID id:found){long number=jdbc.queryForObject("SELECT id_pedido FROM lamontana.pedido WHERE codigo_publico=?",Long.class,id);codigos.asegurar(number);var secrets=jdbc.query("SELECT codigo_publico,codigo_cifrado FROM lamontana.codigo_entrega WHERE id_pedido=? AND revocado_en IS NULL AND utilizado_en IS NULL",(r,n)->new Object[]{r.getObject(1,UUID.class),r.getString(2)},number);for(var secret:secrets)if(secret[1]!=null&&MessageDigest.isEqual(codigos.texto((UUID)secret[0],(String)secret[1]).getBytes(StandardCharsets.UTF_8),text.toUpperCase(Locale.ROOT).getBytes(StandardCharsets.UTF_8)))match=id;}
   if(match!=null){filter+=" AND p.codigo_publico=?";args.add(match);}else{filter+=" AND lower(u.nombre||' '||u.apellido) LIKE ?";args.add("%"+text.toLowerCase(Locale.ROOT)+"%");}
  }else if(!text.isBlank()){filter+=" AND (lower(u.nombre||' '||u.apellido) LIKE ? OR lower(u.correo) LIKE ? OR ('PED-'||p.id_pedido) ILIKE ? OR p.id_pedido::text=?)";String query="%"+text.toLowerCase(Locale.ROOT)+"%";args.addAll(List.of(query,query,query,text));}
  long count=jdbc.queryForObject("SELECT count(*)"+FROM+filter,Long.class,args.toArray());args.add(in.pagina()*25);var rows=jdbc.query(SELECT+FROM+filter+" ORDER BY movimiento DESC,p.id_pedido DESC LIMIT 25 OFFSET ?",this::fila,args.toArray());return new Bandeja(rows,count,in.pagina());
 }
 @Transactional public Ficha ficha(UUID id,String correo){locks();acceso(correo);CuentaPuntoAcceso.pedido(jdbc,correo,id);var p=pedidos.detalle(id,correo,true);var row=jdbc.queryForObject(SELECT+FROM+" AND p.codigo_publico=?",this::fila,acceso(correo).punto(),id);var d=entregas.consultar(id,correo,true);var medios=acceso(correo).cobros()?pagos.vista(p.cotizacion(),correo,true).mediosRecepcion().stream().map(Enum::name).toList():List.<String>of();return new Ficha(row,p.oferta().items().stream().map(i->new Trabajo(i.documento().nombre(),i.trabajo().paginas(),i.trabajo().copias())).toList(),d,medios);}
 @Transactional public Bandeja recibir(Recepcion in,String correo){locks();var a=acceso(correo);if(in.pedidos().stream().map(PedidoLote::pedido).distinct().count()!=in.pedidos().size())throw error(HttpStatus.BAD_REQUEST,"No repitas pedidos.");String hash=hash(in.pedidos().stream().sorted(Comparator.comparing(PedidoLote::pedido)).toList());var old=jdbc.query("SELECT id_usuario,huella FROM lamontana.recepcion_lote_punto WHERE id_operacion=?",(r,n)->new Object[]{r.getLong(1),r.getString(2)},in.operacion());if(!old.isEmpty()){if((long)old.get(0)[0]!=a.usuario()||!old.get(0)[1].equals(hash))throw error(HttpStatus.CONFLICT,"La operación ya tiene otros datos.");return buscar(new Buscar("POR_LLEGAR","",0),correo);}
  for(var p:in.pedidos())CuentaPuntoAcceso.pedido(jdbc,correo,p.pedido());for(var p:in.pedidos())entregas.mover(p.pedido(),new ar.com.lamontana.entregas.EntregaController.Movimiento(UUID.nameUUIDFromBytes((in.operacion()+":"+p.pedido()).getBytes(StandardCharsets.UTF_8)),p.version(),Accion.LLEGAR_PUNTO,null,true),correo);
  jdbc.update("INSERT INTO lamontana.recepcion_lote_punto VALUES (?,?,?,?,?,?)",in.operacion(),a.punto(),a.usuario(),hash,in.pedidos().size(),Timestamp.from(Instant.now()));return buscar(new Buscar("POR_LLEGAR","",0),correo);
 }
 @Transactional public EntregaService.Validacion entregar(UUID id,Recibir in,String correo){locks();acceso(correo);CuentaPuntoAcceso.pedido(jdbc,correo,id);var v=entregas.recibir(id,in,correo);if(v.aceptado()&&v.vista().cierre()==null&&v.vista().bloqueosCierre().isEmpty()){var closed=entregas.cerrar(id,new Cerrar(UUID.nameUUIDFromBytes((in.operacion()+":cerrar").getBytes(StandardCharsets.UTF_8)),v.vista().version(),null,true),correo);return new EntregaService.Validacion(closed,true,"Pedido entregado y cerrado.");}return v;}
 @Transactional public EntregaService.Validacion efectivo(UUID id,CobrarEntregar in,String correo){locks();acceso(correo);CuentaPuntoAcceso.pedido(jdbc,correo,id);return entregas.cobrarEntregar(id,in,correo);}
 @Transactional public Ficha cobrar(UUID id,Cobro in,String correo){locks();var a=acceso(correo);if(!a.cobros())throw error(HttpStatus.FORBIDDEN,"Esta cuenta no tiene habilitados los cobros.");CuentaPuntoAcceso.pedido(jdbc,correo,id);var p=pedidos.detalle(id,correo,true);if(!in.confirmado())throw error(HttpStatus.BAD_REQUEST,"Confirmá el dinero recibido.");UUID operation=UUID.nameUUIDFromBytes((id+":"+in.operacion()).getBytes(StandardCharsets.UTF_8));
  boolean replay=Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM lamontana.evento_financiero WHERE id_operacion=?)",Boolean.class,operation));
  if(!replay){if(p.version()!=in.version()||!p.estadoLogistico().equals("DISPONIBLE_PUNTO"))throw error(HttpStatus.CONFLICT,"El pedido cambió o todavía no llegó al punto.");BigDecimal amount=new BigDecimal(in.importe()),pending=new BigDecimal(pagos.vista(p.cotizacion(),correo,true).pendiente());if(amount.signum()<=0||amount.compareTo(pending)>0)throw error(HttpStatus.CONFLICT,"El importe supera el saldo pendiente. Actualizá el pedido.");}
  pagos.recibir(p.cotizacion(),new PagoController.Recibir(operation,null,in.medio(),in.importe(),in.referencia(),null,true,"Cobro recibido en "+a.nombre()+" para PED-"+p.numero()+".",true),correo);return ficha(id,correo);
 }
 @Transactional(readOnly=true) public Finanzas finanzas(String desde,String hasta,int pagina,String correo){var a=acceso(correo);if(pagina<0||pagina>100000)throw error(HttpStatus.BAD_REQUEST,"Página inválida.");var zone=ZoneId.of("America/Argentina/Buenos_Aires");LocalDate start,end;try{start=desde.isBlank()?LocalDate.now(zone).minusMonths(6):LocalDate.parse(desde);end=hasta.isBlank()?LocalDate.now(zone):LocalDate.parse(hasta);}catch(Exception e){throw error(HttpStatus.BAD_REQUEST,"Fechas inválidas.");}if(start.isAfter(end)||start.isBefore(end.minusYears(2)))throw error(HttpStatus.BAD_REQUEST,"Elegí un período de hasta dos años.");var lower=Timestamp.from(start.atStartOfDay(zone).toInstant());var upper=Timestamp.from(end.plusDays(1).atStartOfDay(zone).toInstant());
  String financial=" FROM lamontana.evento_financiero e LEFT JOIN lamontana.pago pa ON pa.id_evento=e.id_evento LEFT JOIN lamontana.aplicacion_pago_cotizacion ap ON ap.id_evento=e.id_evento LEFT JOIN lamontana.reembolso re ON re.id_evento=e.id_evento LEFT JOIN lamontana.pago origin ON origin.id_pago=coalesce(ap.id_pago,re.id_pago) JOIN lamontana.pedido_actual p ON lamontana.cotizacion_descendiente(p.id_cotizacion,e.id_cotizacion) JOIN lamontana.reserva_entrega r USING(id_pedido) JOIN lamontana.punto_entrega pt ON pt.codigo_publico=r.destino_publico WHERE pt.id_punto_entrega=? AND r.modalidad='RETIRO_PUNTO_ENTREGA' AND r.estado IN ('ACTIVA','CUMPLIDA') AND e.tipo IN ('RECIBIR','APLICAR','DEVOLVER') AND e.fecha>=? AND e.fecha<?";Object[] args={a.punto(),lower,upper};
  var sumArgs=new ArrayList<Object>();sumArgs.add(a.usuario());sumArgs.add(a.usuario());sumArgs.addAll(Arrays.asList(args));
  var sums=jdbc.queryForObject("SELECT coalesce(sum(pa.importe) FILTER(WHERE pa.medio='EFECTIVO' AND e.id_actor=?),0),coalesce(sum(pa.importe) FILTER(WHERE pa.medio='TRANSFERENCIA' AND e.id_actor=?),0),count(*)"+financial,(r,n)->new Object[]{r.getBigDecimal(1).toPlainString(),r.getBigDecimal(2).toPlainString(),r.getLong(3)},sumArgs.toArray());
  var parameters=new ArrayList<Object>();parameters.add(a.usuario());parameters.addAll(Arrays.asList(args));parameters.add(pagina*25);var moves=jdbc.query("SELECT p.id_pedido,e.tipo,coalesce(pa.importe,ap.importe,re.importe) AS importe,coalesce(pa.medio,re.medio,origin.medio) AS medio,coalesce(pa.referencia,re.referencia,origin.referencia) AS referencia,e.actor_nombre,e.fecha,e.id_actor=? AS en_punto"+financial+" ORDER BY e.fecha DESC,e.id_evento DESC LIMIT 25 OFFSET ?",(r,n)->new Movimiento(r.getLong(1),r.getString(2),r.getBigDecimal(3).toPlainString(),r.getString(4),r.getString(5),r.getString(6),r.getTimestamp(7).toInstant(),r.getBoolean(8)),parameters.toArray());
  String pending=jdbc.queryForObject("SELECT coalesce(sum(greatest(p.total-coalesce((SELECT sum(n.neto) FROM lamontana.aplicacion_pago_neta n WHERE n.id_cotizacion=p.id_cotizacion),0),0)),0)"+FROM+" AND ("+READY+")",BigDecimal.class,a.punto()).toPlainString();return new Finanzas(pending,(String)sums[0],(String)sums[1],(long)sums[2],moves,pagina,start.toString(),end.toString());
 }
 private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsString(value).getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private ResponseStatusException error(HttpStatus s,String m){return new ResponseStatusException(s,m);}
}
